using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.Rendering;using TechnifyERP.Application.Enrollments;
namespace TechnifyERP.Areas.Student.Controllers;
[Area("Student"),Authorize(Roles="Student")]public sealed class EnrollmentsController(IEnrollmentService service):Controller
{public async Task<IActionResult>Index(CancellationToken ct){ViewBag.Courses=(await service.GetAvailableCoursesAsync(Id,ct)).Select(x=>new SelectListItem($"{x.Code} - {x.Name} (Rs. {x.MonthlyFee:N2}/month)",x.Id.ToString()));return View(await service.GetStudentEnrollmentsAsync(Id,ct));}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>RequestEnrollment(int courseId,CancellationToken ct){var r=await service.RequestAsync(Id,courseId,ct);TempData[r==EnrollmentActionResult.Success?"SuccessMessage":"ErrorMessage"]=r==EnrollmentActionResult.Success?"Enrollment request admin ko bhej di gayi.":r==EnrollmentActionResult.Duplicate?"Is course ki request pehle se maujood hai.":"Course request nahi hui.";return RedirectToAction(nameof(Index));}private string Id=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;}
